const expirePendingOrders = `-- name: ExpirePendingOrders :many
WITH expired AS (
  SELECT id FROM orders WHERE state IN ('draft','pending') AND expires_at <= now() FOR UPDATE SKIP LOCKED
), mutations AS (
  INSERT INTO order_mutations (order_id, action, idempotency_key, reason)
  SELECT id, 'expire', 'system:expiry', 'payment window elapsed' FROM expired
  ON CONFLICT DO NOTHING
)
UPDATE orders SET state = 'expired', updated_at = now() WHERE id IN (SELECT id FROM expired)
RETURNING id, user_id, state, operation, currency, subtotal_minor, discount_minor, wallet_minor, external_minor, paid_minor, refunded_minor, idempotency_key, expires_at, created_at, updated_at, subscription_id, selected_squad_ids, paid_at
`

func (q *Queries) ExpirePendingOrders(ctx context.Context) ([]Order, error) {
	rows, err := q.db.Query(ctx, expirePendingOrders)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Order{}
	for rows.Next() {
		var i Order
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.State,
			&i.Operation,
			&i.Currency,
			&i.SubtotalMinor,
			&i.DiscountMinor,
			&i.WalletMinor,
			&i.ExternalMinor,
			&i.PaidMinor,
			&i.RefundedMinor,
			&i.IdempotencyKey,
			&i.ExpiresAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.SubscriptionID,
			&i.SelectedSquadIds,
			&i.PaidAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const extendOrderExpiry = `-- name: ExtendOrderExpiry :one
UPDATE orders
SET expires_at = GREATEST(expires_at, $1::timestamptz), updated_at = now()
WHERE id = $2 AND state = 'pending' AND operation <> 'goods'
RETURNING id, user_id, state, operation, currency, subtotal_minor, discount_minor, wallet_minor, external_minor, paid_minor, refunded_minor, idempotency_key, expires_at, created_at, updated_at, subscription_id, selected_squad_ids, paid_at
`

type ExtendOrderExpiryParams struct {
	ExpiresAt pgtype.Timestamptz `json:"expires_at"`
	OrderID   pgtype.UUID        `json:"order_id"`
}

// Lengthens a pending order's payment window for a provider chosen after the
// order was created. GREATEST keeps it from ever shortening one, the state
// guard keeps a closed order closed, and a goods order is excluded because its
// deadline is the gateway quote's validity rather than a payment window.
func (q *Queries) ExtendOrderExpiry(ctx context.Context, arg ExtendOrderExpiryParams) (Order, error) {
	row := q.db.QueryRow(ctx, extendOrderExpiry, arg.ExpiresAt, arg.OrderID)
	var i Order
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.State,
		&i.Operation,
		&i.Currency,
		&i.SubtotalMinor,
		&i.DiscountMinor,
		&i.WalletMinor,
		&i.ExternalMinor,
		&i.PaidMinor,
		&i.RefundedMinor,
		&i.IdempotencyKey,
		&i.ExpiresAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.SubscriptionID,
		&i.SelectedSquadIds,
		&i.PaidAt,
	)
	return i, err
}

const getAvailableWalletBalance = `-- name: GetAvailableWalletBalance :one
SELECT GREATEST(
  COALESCE((SELECT sum(wallet_entry.amount_minor)
            FROM ledger_entries wallet_entry
            WHERE wallet_entry.account_type = 'customer_wallet' AND wallet_entry.user_id = $1 AND wallet_entry.currency = $2), 0)
  - COALESCE((SELECT sum(reserved_order.wallet_minor)
              FROM orders reserved_order
              WHERE reserved_order.user_id = $1 AND reserved_order.currency = $2
                AND reserved_order.state IN ('draft', 'pending')), 0),
  0
)::bigint AS balance_minor
`

